# ---------------------------------------------------------------------------------------
# Job body (appended verbatim to every sbatch generated by launch.sh; the settings block
# above it defines WORKDIR, MODE, EXP_NAME, RUN_DIR, IMAGE, TRAIN_ARGS, ...).
# ---------------------------------------------------------------------------------------
set -o pipefail
ulimit -c 0
RESUBMIT_COUNT=${RESUBMIT_COUNT:-0}
echo "START $(date)  job=$SLURM_JOB_ID  nodes=$SLURM_NNODES ($SLURM_JOB_NODELIST)"
echo "mode=$MODE  exp=$EXP_NAME  resubmit=$RESUBMIT_COUNT/$MAX_RESUBMITS"

NETLOG_DIR=$RUN_DIR/netlogs/job_$SLURM_JOB_ID
NSYS_DIR=$RUN_DIR/nsys/job_$SLURM_JOB_ID
mkdir -p "$RUN_DIR"/{logs,tensorboard,wandb} "$NETLOG_DIR" "$CACHE_ROOT" "$CODE_ROOT"
# This very script (Slurm's copy, not logs/<job>.sbatch which a later launch.sh may regenerate):
# resubmissions run exactly what was submitted.
SELF=$RUN_DIR/logs/sbatch-$SLURM_JOB_ID.sh
cp "$0" "$SELF" 2>/dev/null || SELF=$SCRIPT_PATH
echo "scripts: $SRC"
if [ "$MODE" = smoke ] && [ -d "$RUN_DIR/checkpoints" ]; then
    # Smoke checkpoints are disposable; dist-checkpointing refuses to write into an existing iter dir.
    echo "smoke: removing previous smoke checkpoints in $RUN_DIR/checkpoints"
    rm -rf "$RUN_DIR/checkpoints"
fi

########## Code snapshot: pinned Megatron-Bridge + Megatron-LM + patches/ ##########
# Content-addressed and shared by all jobs with the same code; the user's submodule
# working trees are never touched. Mounted at /opt/Megatron-Bridge in the container.
PATCH_HASH=$(cat "$SRC"/patches/megatron-bridge/*.patch "$SRC"/patches/megatron-lm/*.patch 2>/dev/null \
    | sha256sum | cut -c1-12)
CODE_ID=mb-${MBRIDGE_COMMIT:0:10}_mlm-${MLM_COMMIT:0:10}_p-$PATCH_HASH
SNAP=$CODE_ROOT/$CODE_ID
echo "code snapshot: $SNAP"
(
    flock 9
    if [ ! -f "$SNAP/.src_ready" ]; then
        set -e
        export GIT_CEILING_DIRECTORIES=$CODE_ROOT
        TMP=$SNAP.tmp.$SLURM_JOB_ID
        rm -rf "$TMP"
        mkdir -p "$TMP/3rdparty/Megatron-LM"
        git -C "$WORKDIR/Megatron-Bridge" archive "$MBRIDGE_COMMIT" | tar -x -C "$TMP"
        git -C "$WORKDIR/Megatron-Bridge/3rdparty/Megatron-LM" archive "$MLM_COMMIT" | tar -x -C "$TMP/3rdparty/Megatron-LM"
        for target in megatron-bridge:. megatron-lm:3rdparty/Megatron-LM; do
            for p in "$SRC/patches/${target%%:*}"/*.patch; do
                [ -e "$p" ] || continue
                echo "  apply ${target%%:*}/$(basename "$p")"
                (cd "$TMP/${target#*:}" && git apply --whitespace=nowarn "$p")
            done
        done
        touch "$TMP/.src_ready"
        rm -rf "$SNAP"   # a leftover without .src_ready is an aborted attempt
        mv "$TMP" "$SNAP"
    fi
) 9>"$CODE_ROOT/.lock" || { echo "ERROR: could not build the code snapshot"; exit 1; }

########## Container (EDF) ##########
EDF=$RUN_DIR/logs/edf-$SLURM_JOB_ID.toml
cat > "$EDF" <<EOF
image = "$IMAGE"
mounts = ["/capstor", "/iopsstor", "/users", "$SNAP:/opt/Megatron-Bridge"]
workdir = "$WORKDIR"
writable = true
entrypoint = true

[env]
PMIX_MCA_psec = "native"

[annotations]
com.hooks.cxi.enabled = "false"
EOF
SRUN_FLAGS=(--mpi=pmix --network=disable_rdzv_get --environment="$EDF")

########## Runtime environment ##########
export WORKDIR SRC NETLOG NETLOG_DIR NETMON_INTERVAL NETMON_NVLINK_EVERY NSYS NSYS_RANKS NSYS_DIR NSYS_TRACE
export HF_HOME HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 HF_DATASETS_OFFLINE=1
# JIT caches on node-local tmpfs: no cross-node races on Lustre, no stale entries.
export TRITON_CACHE_DIR=/tmp/$USER/triton TORCHINDUCTOR_CACHE_DIR=/tmp/$USER/inductor
# Also keep Triton autotuning results there (Gated DeltaNet kernels): a training process restarted
# in the same job (batch-size steps) does not re-benchmark every config.
export TRITON_CACHE_AUTOTUNING=1
export TORCH_EXTENSIONS_DIR=/tmp/$USER/torch_extensions XDG_CACHE_HOME=/tmp/$USER/xdg
# Megatron-Bridge's COMMON_RECIPE_ENV_VARS (used by its benchmark recipes).
export NCCL_GRAPH_REGISTER=0 NCCL_NVLS_ENABLE=0 PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export TORCH_NCCL_AVOID_RECORD_STREAMS=1 TORCH_NCCL_HIGH_PRIORITY=1
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-8}
export NCCL_DEBUG=${NCCL_DEBUG:-WARN}

if [ "$NETLOG" -ge 2 ]; then
    # NCCL inspector (built into the image with NCCL 2.30.7): one JSON record per NCCL
    # collective and per P2P send/recv (MoE all-to-all, DP reduce-scatter/all-gather, ...),
    # on every rank: op, bytes, GPU-timed duration, algorithm bandwidth, communicator name.
    export NCCL_PROFILER_PLUGIN=/usr/local/lib/libnccl-profiler-inspector.so
    export NCCL_INSPECTOR_ENABLE=1
    export NCCL_INSPECTOR_DUMP_DIR=$NETLOG_DIR/nccl-inspector
    export NCCL_INSPECTOR_DUMP_THREAD_INTERVAL_MICROSECONDS=${NCCL_INSPECTOR_INTERVAL_US:-1000000}
    export NCCL_INSPECTOR_DUMP_MIN_SIZE_BYTES=0          # every op, also the small ones
    export NCCL_INSPECTOR_ENABLE_P2P=1
    export NCCL_INSPECTOR_DUMP_COLL_RING_SIZE=65536      # no ring overwrite between dumps
    export NCCL_INSPECTOR_DUMP_P2P_RING_SIZE=65536
    export NCCL_INSPECTOR_REQUIRE_KERNEL_TIMING=0        # keep ops with CPU-side timing too
    [ "$NETLOG" -ge 3 ] && export NCCL_INSPECTOR_DUMP_VERBOSE=1   # + per-op/channel timestamps
    mkdir -p "$NCCL_INSPECTOR_DUMP_DIR"
fi
[ "$NETLOG" -ge 1 ] && TRAIN_ARGS+=(--net-log-dir "$NETLOG_DIR/steps")
if [ "$NSYS" = 1 ]; then
    TRAIN_ARGS+=(--nsys-steps "$NSYS_STEPS" --nsys-ranks "$NSYS_RANKS")
    mkdir -p "$NSYS_DIR"
fi

if [ -n "${WANDB_API_KEY:-}" ] || [ "$WANDB_MODE" = offline ]; then
    # One W&B run per experiment, continued across resubmitted jobs.
    [ -s "$RUN_DIR/wandb/run_id" ] || echo "${EXP_NAME:0:48}-$(date +%s)" | tr -c 'A-Za-z0-9_\n-' '_' > "$RUN_DIR/wandb/run_id"
    export WANDB_RUN_ID=$(cat "$RUN_DIR/wandb/run_id") WANDB_RESUME=allow WANDB_DIR=$RUN_DIR/wandb
    [ -n "$WANDB_MODE" ] && export WANDB_MODE
    TRAIN_ARGS+=(logger.wandb_project="$WANDB_PROJECT" logger.wandb_exp_name="$EXP_NAME"
                 logger.wandb_save_dir="$RUN_DIR/wandb")
    [ -n "${WANDB_ENTITY:-}" ] && TRAIN_ARGS+=(logger.wandb_entity="$WANDB_ENTITY")
    echo "W&B: project=$WANDB_PROJECT run=$WANDB_RUN_ID${WANDB_MODE:+ mode=$WANDB_MODE}"
    [ "$WANDB_MODE" = offline ] && echo "W&B offline: upload later with  wandb sync $RUN_DIR/wandb/wandb/offline-run-*"
else
    export WANDB_MODE=disabled
    echo "W&B disabled (WANDB_API_KEY is not set in config.sh)"
fi

########## Pre-step: node health on every node; on node 0 build dataset helpers, record versions ##########
# A node whose GPUs are not usable (seen once after a hung Slurm prolog: "No CUDA GPUs are
# available" on all its ranks) would otherwise fail the job minutes later inside Megatron.
BADNODES=$RUN_DIR/logs/badnodes-$SLURM_JOB_ID
rm -f "$BADNODES"
export BADNODES
# The lock only serializes the first compile of a snapshot; afterwards jobs starting at the
# same time do not wait for each other.
PRESTEP_LOCK=$CODE_ROOT/.lock
[ -f "$SNAP/.helpers_ready" ] && PRESTEP_LOCK=$RUN_DIR/logs/.prestep-$SLURM_JOB_ID.lock
(
    flock 9
    srun -N "$SLURM_NNODES" --ntasks-per-node=1 "${SRUN_FLAGS[@]}" bash -c '
        n=$(python -c "import torch; print(torch.cuda.device_count())" 2>/dev/null | tail -1)
        echo "[health] $(hostname): torch sees ${n:-0} GPUs"
        if [ "${n:-0}" != 4 ]; then echo "$(hostname)" >> "$BADNODES"; exit 3; fi
        [ "$SLURM_NODEID" = 0 ] || exit 0
        set -e
        cd /opt/Megatron-Bridge/3rdparty/Megatron-LM/megatron/core/datasets
        [ -f /opt/Megatron-Bridge/.helpers_ready ] || { make -s && touch /opt/Megatron-Bridge/.helpers_ready; }
        python - <<PY || echo "[versions] probe failed (informational only)"
import ctypes, importlib.metadata as md
def ver(p):
    try:
        return md.version(p)
    except md.PackageNotFoundError:
        return "?"
import torch
lib = sorted({l.split()[-1] for l in open("/proc/self/maps") if "libnccl.so" in l})
v = ctypes.c_int(); ctypes.CDLL(lib[0] if lib else "libnccl.so.2").ncclGetVersion(ctypes.byref(v))
print("[versions] nccl", v.value, "(torch maps", lib, ") | " + " | ".join(
    f"{p} {ver(p)}" for p in ("torch", "megatron-core", "megatron-bridge", "transformer-engine",
                              "transformers", "flash-linear-attention", "wandb")))
import megatron.bridge
print("[versions] megatron.bridge imported from", megatron.bridge.__file__)
PY'
) 9>"$PRESTEP_LOCK"
PRE_RC=$?
rm -f "$RUN_DIR/logs/.prestep-$SLURM_JOB_ID.lock"
if [ "$PRE_RC" -ne 0 ]; then
    BAD=$(sort -u "$BADNODES" 2>/dev/null | paste -sd, -)
    if [ -n "$BAD" ]; then
        echo "ERROR: unusable node(s): $BAD"
        if [ "$RESUBMIT" = true ] && [ "$RESUBMIT_COUNT" -lt "$MAX_RESUBMITS" ]; then
            sbatch --chdir="$WORKDIR" --exclude="$BAD" --export=ALL,RESUBMIT_COUNT=$((RESUBMIT_COUNT + 1)) "$SELF"
        else
            echo "resubmit by hand: sbatch --exclude=$BAD $SELF"
        fi
    else
        echo "ERROR: pre-step failed (container / code snapshot)"
    fi
    exit 1
fi

########## Training ##########
time_left_mins() {  # minutes left in this allocation (squeue %L is [D-]HH:MM:SS or MM:SS)
    local left d=0 h=0 m=0 parts
    left=$(squeue -h -j "$SLURM_JOB_ID" -o %L 2>/dev/null | head -1)
    [[ $left == *-* ]] && { d=${left%%-*}; left=${left#*-}; }
    IFS=: read -r -a parts <<< "$left"
    case ${#parts[@]} in
        3) h=${parts[0]}; m=${parts[1]} ;;
        2) m=${parts[0]} ;;
        *) echo 0; return ;;
    esac
    echo $(( (10#$d * 24 + 10#$h) * 60 + 10#$m ))
}
TRAIN_CMD=(python "$SRC/train/pretrain.py" "${TRAIN_ARGS[@]}")
# With a global-batch-size schedule the training process ends at every batch-size step, after a
# checkpoint (BatchSizeStepCallback in train/pretrain.py), and is started again here in the same
# allocation: it resumes with the new microbatch count and captures its CUDA graphs for it.
BATCH_STEP_MARKER=$RUN_DIR/logs/batch-step-$SLURM_JOB_ID.json
[ "${BATCH_SCHEDULE:-0}" = 1 ] && TRAIN_CMD+=(--batch-step-marker "$BATCH_STEP_MARKER")
while true; do
    rm -f "$BATCH_STEP_MARKER"
    printf 'CMD:'; printf ' %q' "${TRAIN_CMD[@]}"; echo
    srun -l -u "${SRUN_FLAGS[@]}" --cpus-per-task="$SLURM_CPUS_PER_TASK" --kill-on-bad-exit=1 --wait=120 \
        bash "$SRC/train/rank_wrapper.sh" "${TRAIN_CMD[@]}"
    SRUN_RC=$?
    echo "END $(date)  srun exit code: $SRUN_RC"
    { [ "$SRUN_RC" -eq 0 ] && [ -s "$BATCH_STEP_MARKER" ]; } || break
    LEFT=$(time_left_mins)
    echo "[batch-size step] $(tr -d '\n' < "$BATCH_STEP_MARKER"); ${LEFT} min left in this job"
    # Restart needs ~5 min to start plus the 15 min exit margin; otherwise the next job continues.
    if [ "$LEFT" -lt 25 ]; then
        echo "[batch-size step] too little time left in this job; $([ "$RESUBMIT" = true ] \
            && echo "the resubmitted job continues" || echo "continue with a new job (checkpoint saved)")"
        break
    fi
    # The new process measures its own run time: stop it before this job's wall time too.
    NEXT=(); for a in "${TRAIN_CMD[@]}"; do [[ $a == train.exit_duration_in_mins=* ]] || NEXT+=("$a"); done
    TRAIN_CMD=("${NEXT[@]}" "train.exit_duration_in_mins=$((LEFT - 15))")
done

########## Network logs: compress + summarize ##########
if [ "$NETLOG" -ge 1 ]; then
    if [ "$SUMMARIZE" = 1 ]; then
        srun -N1 -n1 "${SRUN_FLAGS[@]}" python "$SRC/tools/summarize_netlogs.py" "$NETLOG_DIR" || true
    fi
    if [ -d "$NETLOG_DIR/nccl-inspector" ]; then
        du -sh "$NETLOG_DIR/nccl-inspector" 2>/dev/null
        find "$NETLOG_DIR/nccl-inspector" -name '*.log' -print0 | xargs -0 -r -P 32 -n 4 gzip -1
    fi
fi

########## Auto-resubmit (train mode) ##########
# Only after a clean exit (Megatron saves and exits before the wall time), so a crash
# never turns into a resubmission loop.
if [ "$RESUBMIT" = true ] && [ "$SRUN_RC" -eq 0 ]; then
    LATEST=$(cat "$RUN_DIR/checkpoints/latest_checkpointed_iteration.txt" 2>/dev/null || echo 0)
    NEXT=$((RESUBMIT_COUNT + 1))
    echo "[resubmit] latest_iter=$LATEST target=$TRAIN_ITERS attempt=$NEXT/$MAX_RESUBMITS"
    if [ "$LATEST" -ge "$TRAIN_ITERS" ]; then
        echo "[resubmit] training complete"
    elif [ "$NEXT" -gt "$MAX_RESUBMITS" ]; then
        echo "[resubmit] MAX_RESUBMITS reached"
    elif [ "$LATEST" -eq 0 ]; then
        echo "[resubmit] no checkpoint written by this job, not resubmitting"
    else
        sbatch --chdir="$WORKDIR" --export=ALL,RESUBMIT_COUNT=$NEXT "$SELF"
    fi
fi
exit $SRUN_RC
